window.TRILHA_GOLD_BANKS=window.TRILHA_GOLD_BANKS||{};window.TRILHA_GOLD_BANKS["v5-sc-A7"]={"id":"sc-A7","title":"Crises convulsivas em pediatria | 30 questões clínicas autorais","group":"P2 • Saúde da Criança II","source":"Biblioteca da Trilha de Ouro SDCII A7, abordagem de crises e estado de mal; enunciados autorais. Conferir doses e sequência com PALS e protocolo local, pois referências podem diferir.","version":"5.1.0","questions":[{"id":"ouro-rigor5-sc-A7-01","topicId":"sc-A7","stem":"Menino de 6 anos tem contrações tônico-clônicas contínuas há 6 minutos, sem recuperação de consciência, apesar de proteção contra trauma e monitorização. Qual classificação operacional muda imediatamente a conduta?","options":["Crise febril simples, mesmo sem febre e com progressão além de 5 minutos.","Estado de mal somente quando atingir 30 minutos; até lá não deve ser tratado.","Síncope prolongada por definição, porque perda de consciência acompanha os movimentos.","Estado de mal convulsivo operacional: tratar a partir de cerca de 5 minutos.","Movimentos benignos, porque crises motoras não causam alterações metabólicas."],"answer":3,"analysis":["INCORRETA. Não há febre e a urgência é a duração prolongada.","INCORRETA. O limiar operacional terapêutico é anterior aos 30 minutos.","INCORRETA. Movimentos contínuos tônico-clônicos são compatíveis com crise convulsiva.","CORRETA. Crise tônico-clônica generalizada além do ponto de intervenção de 5 minutos tem baixa chance de resolução imediata sem tratamento e pode agravar danos.","INCORRETA. Crises prolongadas podem causar hipoxemia, acidose e lesão."],"explanation":"Crise tônico-clônica generalizada além do ponto de intervenção de 5 minutos tem baixa chance de resolução imediata sem tratamento e pode agravar danos.","memorizar":"CRISE CONVULSIVA ≥5 MIN: tratar como STATUS, sem aguardar 30 minutos.","source":"Biblioteca da Trilha de Ouro SDCII A7, abordagem de crises e estado de mal; enunciados autorais. Conferir doses e sequência com PALS e protocolo local, pois referências podem diferir.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Crises convulsivas em pediatria","group":"P2 • Saúde da Criança II","competence":"tempo de status","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"moderada"},{"id":"ouro-rigor5-sc-A7-02","topicId":"sc-A7","stem":"Lactente de 20 meses convulsiona na sala de emergência e apresenta secreção oral, cianose intermitente e saturação flutuante. Qual é a abordagem simultânea à terapia anticonvulsivante?","options":["Introduzir um objeto rígido entre os dentes para impedir mordedura da língua.","Garantir via aérea, oxigenação, ventilação e glicemia junto à terapêutica.","Imobilizar braços e pernas com força para interromper os movimentos.","Esperar cessar toda contração para checar respiração, pois a crise não altera ventilação.","Priorizar entrevista social prolongada em vez do ABCDE."],"answer":1,"analysis":["INCORRETA. Objetos na boca causam trauma e obstrução.","CORRETA. A crise prolongada ameaça via aérea e oxigenação; suporte fisiológico deve ocorrer em paralelo ao anticonvulsivante.","INCORRETA. Contenção agressiva aumenta risco de lesão.","INCORRETA. Hipoventilação e hipóxia exigem avaliação contínua.","INCORRETA. Anamnese é útil, mas riscos respiratórios imediatos vêm antes."],"explanation":"A crise prolongada ameaça via aérea e oxigenação; suporte fisiológico deve ocorrer em paralelo ao anticonvulsivante.","memorizar":"CONVULSÃO: ABCDE + GLICEMIA + ANTICONVULSIVANTE SEM ATRASO.","source":"Biblioteca da Trilha de Ouro SDCII A7, abordagem de crises e estado de mal; enunciados autorais. Conferir doses e sequência com PALS e protocolo local, pois referências podem diferir.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Crises convulsivas em pediatria","group":"P2 • Saúde da Criança II","competence":"ABCDE no atendimento","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"difícil"},{"id":"ouro-rigor5-sc-A7-03","topicId":"sc-A7","stem":"Criança de 5 anos permanece em crise generalizada por 7 minutos, com glicemia normal, acesso venoso funcional e suporte respiratório presente. Qual classe é usualmente primeira linha para interromper a crise?","options":["Antibiótico intravenoso isolado, porque qualquer crise demanda cobertura antimicrobiana antes do controle motor.","Anti-histamínico sedativo como primeira linha específica por ter ação anticonvulsivante garantida.","Manobra vagal como tratamento primário de descarga cortical prolongada.","Diurético osmótico obrigatório antes de tentar qualquer benzodiazepínico.","Benzodiazepínico por via apropriada, conforme protocolo."],"answer":4,"analysis":["INCORRETA. Antibiótico não interrompe crise epileptiforme.","INCORRETA. Não substitui benzodiazepínicos no status.","INCORRETA. Manobras vagais são usadas em arritmias selecionadas, não status convulsivo.","INCORRETA. Osmoterapia depende de indicação intracraniana específica.","CORRETA. Benzodiazepínicos atuam sobre receptores GABA-A e são primeira linha para crise convulsiva prolongada."],"explanation":"Benzodiazepínicos atuam sobre receptores GABA-A e são primeira linha para crise convulsiva prolongada.","memorizar":"STATUS CONVULSIVO: BENZODIAZEPÍNICO é 1ª linha, com suporte ABCDE.","source":"Biblioteca da Trilha de Ouro SDCII A7, abordagem de crises e estado de mal; enunciados autorais. Conferir doses e sequência com PALS e protocolo local, pois referências podem diferir.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Crises convulsivas em pediatria","group":"P2 • Saúde da Criança II","competence":"benzodiazepínico primeira linha","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"difícil"},{"id":"ouro-rigor5-sc-A7-04","topicId":"sc-A7","stem":"Menina de 4 anos convulsiona há 8 minutos, e duas tentativas de acesso venoso falham. A equipe tem medicação anticonvulsivante e dispositivos alternativos disponíveis. Qual decisão evita atraso?","options":["Utilizar benzodiazepínico por via alternativa sem aguardar acesso venoso.","Aguardar exclusivamente acesso central antes de medicar qualquer crise prolongada.","Realizar punção lombar enquanto a criança convulsiona para avaliar causa.","Oferecer comprimido por via oral à criança inconsciente.","Evitar benzodiazepínico porque só é efetivo por via intravenosa."],"answer":0,"analysis":["CORRETA. A ausência de acesso venoso não deve atrasar a primeira linha; vias alternativas têm eficácia no pré-hospitalar e emergência.","INCORRETA. Esse atraso agrava a emergência.","INCORRETA. Estabilização e controle da crise precedem investigação invasiva.","INCORRETA. Via oral durante crise não é segura.","INCORRETA. Existem vias alternativas apropriadas."],"explanation":"A ausência de acesso venoso não deve atrasar a primeira linha; vias alternativas têm eficácia no pré-hospitalar e emergência.","memorizar":"SEM ACESSO NÃO É SEM TRATAMENTO: usar via alternativa de BZD.","source":"Biblioteca da Trilha de Ouro SDCII A7, abordagem de crises e estado de mal; enunciados autorais. Conferir doses e sequência com PALS e protocolo local, pois referências podem diferir.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Crises convulsivas em pediatria","group":"P2 • Saúde da Criança II","competence":"ausência de acesso venoso","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"difícil"},{"id":"ouro-rigor5-sc-A7-05","topicId":"sc-A7","stem":"Criança de 3 anos chega com crise generalizada, palidez e glicemia capilar de 32 mg/dL. A crise persiste enquanto são montados equipamentos. Qual fator desencadeante precisa ser corrigido imediatamente?","options":["Hiperglicemia hiperosmolar, pois qualquer alteração glicêmica medida abaixo de 100 é alta.","Hiponatremia comprovada pelo valor da glicemia.","Corrigir hipoglicemia grave enquanto controla crise e ABCDE.","Epilepsia idiopática confirmada independentemente do metabolismo.","Hipotermia por definição, mesmo sem temperatura registrada."],"answer":2,"analysis":["INCORRETA. 32 mg/dL corresponde a hipoglicemia grave.","INCORRETA. Glicemia não informa sódio sérico.","CORRETA. Neuroglicopenia pode causar crises e lesão; corrigir glicemia é intervenção causal urgente, além de anticonvulsivante quando necessário.","INCORRETA. A hipoglicemia é causa provocadora potencial.","INCORRETA. O valor glicêmico já evidencia urgência metabólica."],"explanation":"Neuroglicopenia pode causar crises e lesão; corrigir glicemia é intervenção causal urgente, além de anticonvulsivante quando necessário.","memorizar":"CRISE + GLICEMIA 32 = CORRIGIR HIPOGLICEMIA IMEDIATAMENTE.","source":"Biblioteca da Trilha de Ouro SDCII A7, abordagem de crises e estado de mal; enunciados autorais. Conferir doses e sequência com PALS e protocolo local, pois referências podem diferir.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Crises convulsivas em pediatria","group":"P2 • Saúde da Criança II","competence":"glicemia baixa","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A7-06","topicId":"sc-A7","stem":"Lactente de 11 meses com gastroenterite recebeu grandes volumes de água livre. Evolui com convulsão, náuseas e sódio sérico de 117 mEq/L. Qual distúrbio explica melhor a crise e exige tratamento dirigido?","options":["Hipernatremia por ingestão de água, cuja osmolaridade aumenta sódio.","Hipocalcemia comprovada porque sódio baixo é equivalente a cálcio baixo.","Convulsão febril simples sem impacto do sódio de 117.","Epilepsia crônica diagnosticada apenas por esta crise provocada.","Hiponatremia sintomática grave com edema cerebral osmótico."],"answer":4,"analysis":["INCORRETA. Água livre tende a reduzir sódio.","INCORRETA. O exame informa sódio, não cálcio.","INCORRETA. Hiponatremia com convulsão é distúrbio metabólico grave.","INCORRETA. Crise aguda sintomática não equivale automaticamente a epilepsia.","CORRETA. Queda acentuada de tonicidade favorece entrada de água nas células cerebrais e convulsão; a correção deve seguir protocolo rigoroso."],"explanation":"Queda acentuada de tonicidade favorece entrada de água nas células cerebrais e convulsão; a correção deve seguir protocolo rigoroso.","memorizar":"HIPONATREMIA GRAVE + CRISE = edema cerebral osmótico; corrigir conforme protocolo.","source":"Biblioteca da Trilha de Ouro SDCII A7, abordagem de crises e estado de mal; enunciados autorais. Conferir doses e sequência com PALS e protocolo local, pois referências podem diferir.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Crises convulsivas em pediatria","group":"P2 • Saúde da Criança II","competence":"hiponatremia sintomática","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A7-07","topicId":"sc-A7","stem":"Escolar de 7 anos recebeu benzodiazepínico em dose apropriada e permanece em crise tônico-clônica, com suporte respiratório em curso. O clínico cogita apenas repetir a mesma medicação indefinidamente. Qual estratégia é mais segura?","options":["Escalonar para segunda linha após benzodiazepínicos adequados.","Repetir benzodiazepínico a cada minuto sem limite porque não há risco de hipoventilação.","Interromper suporte ventilatório para observar somente os movimentos.","Concluir que nenhum fármaco pode ser utilizado após a primeira dose.","Realizar alta porque falha de primeira linha exclui epilepsia."],"answer":0,"analysis":["CORRETA. Repetição excessiva de BZD eleva risco de depressão respiratória, enquanto estado persistente demanda outra classe anticonvulsivante.","INCORRETA. Acúmulo pode deprimir respiração.","INCORRETA. Oxigenação e ventilação permanecem prioritárias.","INCORRETA. O protocolo prevê escalonamento terapêutico.","INCORRETA. Crise persistente é emergência em progressão."],"explanation":"Repetição excessiva de BZD eleva risco de depressão respiratória, enquanto estado persistente demanda outra classe anticonvulsivante.","memorizar":"APÓS BZD ADEQUADO SEM CONTROLE: ESCALONAR, não repetir indefinidamente.","source":"Biblioteca da Trilha de Ouro SDCII A7, abordagem de crises e estado de mal; enunciados autorais. Conferir doses e sequência com PALS e protocolo local, pois referências podem diferir.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Crises convulsivas em pediatria","group":"P2 • Saúde da Criança II","competence":"escalonamento após benzodiazepínico","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A7-08","topicId":"sc-A7","stem":"Adolescente de 13 anos segue convulsionando apesar de benzodiazepínico e anticonvulsivante de segunda linha em doses adequadas. Evolui com acidose e necessidade crescente de suporte respiratório. Qual nível de assistência passa a ser necessário?","options":["Alta para casa com retorno em uma semana por ser adolescente.","Evitar intervenção adicional porque a atividade motora já durou muito.","Realizar EEG ambulatorial isolado antes de qualquer suporte adicional.","Tratar status refratário em UTI com monitorização e suporte avançados.","Prescrever apenas antiemético e aguardar normalização espontânea do pH."],"answer":3,"analysis":["INCORRETA. A crise refratária é risco imediato de lesão e morte.","INCORRETA. Persistência demanda escalonamento.","INCORRETA. Monitorização não substitui estabilização e tratamento intensivo.","CORRETA. Falha de primeira e segunda linhas com deterioração clínica define emergência refratária e requer UTI e controle eletroclínico.","INCORRETA. A acidose decorre do status, que permanece ativo."],"explanation":"Falha de primeira e segunda linhas com deterioração clínica define emergência refratária e requer UTI e controle eletroclínico.","memorizar":"STATUS REFRATÁRIO: UTI + suporte ventilatório + terapia escalonada e EEG.","source":"Biblioteca da Trilha de Ouro SDCII A7, abordagem de crises e estado de mal; enunciados autorais. Conferir doses e sequência com PALS e protocolo local, pois referências podem diferir.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Crises convulsivas em pediatria","group":"P2 • Saúde da Criança II","competence":"status refratário","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A7-09","topicId":"sc-A7","stem":"Menina de 10 anos teve convulsão prolongada tratada, os movimentos cessaram, mas ela permanece em torpor desproporcional ao tempo esperado, com discretos movimentos palpebrais rítmicos. Qual possibilidade deve ser investigada?","options":["Recuperação completa documentada apenas porque os membros pararam de tremer.","Pesquisar status não convulsivo por EEG, além de causas metabólicas.","Hiperventilação voluntária como diagnóstico exclusivo de movimentos palpebrais.","Conversão psicogênica confirmada sem exame neurológico ou EEG.","Crise febril simples porque toda convulsão tratada termina sem sequelas."],"answer":1,"analysis":["INCORRETA. Rebaixamento persistente pode refletir atividade ictal.","CORRETA. A ausência de grandes movimentos não exclui atividade eletrográfica persistente; EEG ajuda a distinguir crises sutis de pós-ictal.","INCORRETA. Há contexto de status e torpor que exige investigação.","INCORRETA. Não é possível atribuir de pronto a causa funcional.","INCORRETA. Não há elementos para essa classificação nem recuperação típica."],"explanation":"A ausência de grandes movimentos não exclui atividade eletrográfica persistente; EEG ajuda a distinguir crises sutis de pós-ictal.","memorizar":"MOVIMENTO CESSOU, CONSCIÊNCIA NÃO VOLTOU: considerar STATUS NÃO CONVULSIVO.","source":"Biblioteca da Trilha de Ouro SDCII A7, abordagem de crises e estado de mal; enunciados autorais. Conferir doses e sequência com PALS e protocolo local, pois referências podem diferir.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Crises convulsivas em pediatria","group":"P2 • Saúde da Criança II","competence":"status não convulsivo","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A7-10","topicId":"sc-A7","stem":"Menino de 2 anos previamente hígido apresentou convulsão tônico-clônica generalizada de 3 minutos com febre 39 °C; recuperou-se rapidamente, tem exame neurológico normal e não houve recorrência em 24 horas. Qual classificação melhor descreve o episódio?","options":["Estado de mal, pois qualquer convulsão febril tem duração clinicamente prolongada.","Convulsão febril complexa porque toda febre acima de 38,5 torna o episódio complexo.","Convulsão febril simples, após excluir sinais de gravidade.","Epilepsia definida por uma crise exclusivamente provocada por febre.","Encefalite confirmada apesar de exame neurológico e recuperação normais."],"answer":2,"analysis":["INCORRETA. A crise durou 3 minutos.","INCORRETA. Complexidade se relaciona a duração, focalidade ou recorrência.","CORRETA. Idade típica, caráter generalizado, duração breve e ausência de recorrência no mesmo episódio febril favorecem crise febril simples.","INCORRETA. Uma crise febril simples não define epilepsia.","INCORRETA. O caso não fornece evidências de disfunção cerebral persistente."],"explanation":"Idade típica, caráter generalizado, duração breve e ausência de recorrência no mesmo episódio febril favorecem crise febril simples.","memorizar":"FEBRIL SIMPLES: generalizada, breve, única em 24 h, recuperação típica.","source":"Biblioteca da Trilha de Ouro SDCII A7, abordagem de crises e estado de mal; enunciados autorais. Conferir doses e sequência com PALS e protocolo local, pois referências podem diferir.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Crises convulsivas em pediatria","group":"P2 • Saúde da Criança II","competence":"febril simples critérios","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"moderada"},{"id":"ouro-rigor5-sc-A7-11","topicId":"sc-A7","stem":"Criança de 19 meses apresenta crise febril de 4 minutos com movimentos apenas do membro superior direito. Recupera interação após 15 minutos. O residente considera a crise simples pela duração. Qual parâmetro muda a classificação?","options":["O limite térmico, pois somente febre acima de 40 °C define complexidade.","Focalidade torna a crise febril complexa, mesmo breve.","A recuperação em 15 minutos torna qualquer crise focal simples.","A idade de 19 meses exclui convulsões febris.","O membro acometido, pois lado direito exclui origem cortical."],"answer":1,"analysis":["INCORRETA. A intensidade da febre não é critério isolado de complexidade.","CORRETA. Duração curta não neutraliza a natureza focal; qualquer característica de focalidade exige classificação e avaliação diferentes.","INCORRETA. A focalidade continua caracterizando complexidade.","INCORRETA. A idade está na faixa típica.","INCORRETA. Semiótica focal é compatível com origem cortical localizada."],"explanation":"Duração curta não neutraliza a natureza focal; qualquer característica de focalidade exige classificação e avaliação diferentes.","memorizar":"FEBRIL FOCAL = COMPLEXA, ainda que dure 4 minutos.","source":"Biblioteca da Trilha de Ouro SDCII A7, abordagem de crises e estado de mal; enunciados autorais. Conferir doses e sequência com PALS e protocolo local, pois referências podem diferir.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Crises convulsivas em pediatria","group":"P2 • Saúde da Criança II","competence":"febril complexa focal","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"difícil"},{"id":"ouro-rigor5-sc-A7-12","topicId":"sc-A7","stem":"Menina de 3 anos tem dois episódios convulsivos generalizados de 2 minutos separados por 5 horas durante a mesma infecção febril, com recuperação intercrítica normal. Por que não é classificada como febril simples?","options":["Porque toda febre com duas crises prova meningite bacteriana.","Porque qualquer episódio de 2 minutos já ultrapassa limite de status.","Porque 3 anos está fora da faixa de convulsão febril.","Recorrência em 24 h caracteriza convulsão febril complexa.","Porque duas crises comprovam epilepsia genética sem investigação."],"answer":3,"analysis":["INCORRETA. Recorrência exige avaliação, mas não define etiologia.","INCORRETA. Crise de 2 minutos não alcança 5 minutos.","INCORRETA. Três anos está na faixa habitual.","CORRETA. Focalidade, duração prolongada ou recorrência em 24 horas são critérios de complexidade; basta um deles.","INCORRETA. Crises provocadas por febre não definem epilepsia automaticamente."],"explanation":"Focalidade, duração prolongada ou recorrência em 24 horas são critérios de complexidade; basta um deles.","memorizar":"REPETIU em 24 HORAS: febril COMPLEXA.","source":"Biblioteca da Trilha de Ouro SDCII A7, abordagem de crises e estado de mal; enunciados autorais. Conferir doses e sequência com PALS e protocolo local, pois referências podem diferir.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Crises convulsivas em pediatria","group":"P2 • Saúde da Criança II","competence":"febril recorrente","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"difícil"},{"id":"ouro-rigor5-sc-A7-13","topicId":"sc-A7","stem":"Pais de um menino de 18 meses que teve convulsão febril simples pedem fenobarbital diário para prevenir qualquer evento futuro. A criança está hígida e tem desenvolvimento normal. Qual orientação é mais coerente?","options":["Evitar anticonvulsivante diário de rotina; orientar família.","Instituir fenobarbital vitalício após qualquer crise febril breve.","Garantir que nunca mais haverá outra crise, dispensando orientações.","Suspender vacinas futuras por ser a única maneira comprovada de prevenir crises.","Atribuir o episódio a dano neurológico permanente, mesmo sem sinais."],"answer":0,"analysis":["CORRETA. Riscos de efeitos adversos de profilaxia contínua superam benefícios na maioria dos casos de crise febril simples.","INCORRETA. Crise febril simples não indica profilaxia contínua de rotina.","INCORRETA. Existe possibilidade de recorrência.","INCORRETA. Vacinação é relevante e não deve ser abandonada por crise febril simples.","INCORRETA. Crise febril simples geralmente tem prognóstico favorável."],"explanation":"Riscos de efeitos adversos de profilaxia contínua superam benefícios na maioria dos casos de crise febril simples.","memorizar":"FEBRIL SIMPLES: orientar e acompanhar, não antiepiléptico diário de rotina.","source":"Biblioteca da Trilha de Ouro SDCII A7, abordagem de crises e estado de mal; enunciados autorais. Conferir doses e sequência com PALS e protocolo local, pois referências podem diferir.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Crises convulsivas em pediatria","group":"P2 • Saúde da Criança II","competence":"prevenção crônica após febril simples","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"moderada"},{"id":"ouro-rigor5-sc-A7-14","topicId":"sc-A7","stem":"Escolar de 8 anos sofre crise focal que inicia na mão esquerda e se generaliza. Após cessar, permanece com paresia do braço esquerdo durante 25 minutos, com melhora gradual. Qual diagnóstico diferencial é importante reconhecer?","options":["Miastenia gravis confirmada porque qualquer fraqueza após exercício é autoimune.","Lesão medular obrigatória, pois o déficit aparece no braço.","Considerar paresia de Todd, investigando causas graves se indicado.","Ausência epiléptica como causa única do déficit motor duradouro.","Simulação como diagnóstico seguro, porque a fraqueza está melhorando."],"answer":2,"analysis":["INCORRETA. Início temporal após crise focal favorece déficit pós-ictal.","INCORRETA. Não há trauma ou padrão medular.","CORRETA. Déficit focal ipsilateral à manifestação inicial pode persistir temporariamente após descarga focal; não exclui AVC e outras causas sem avaliação.","INCORRETA. Ausências típicas são breves e sem paresia focal pós-ictal.","INCORRETA. Melhora gradual é compatível com déficit pós-ictal, sem permitir rotulagem funcional."],"explanation":"Déficit focal ipsilateral à manifestação inicial pode persistir temporariamente após descarga focal; não exclui AVC e outras causas sem avaliação.","memorizar":"DÉFICIT FOCAL APÓS CRISE = considerar TODD, sem negligenciar AVC.","source":"Biblioteca da Trilha de Ouro SDCII A7, abordagem de crises e estado de mal; enunciados autorais. Conferir doses e sequência com PALS e protocolo local, pois referências podem diferir.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Crises convulsivas em pediatria","group":"P2 • Saúde da Criança II","competence":"paralisia de Todd","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A7-15","topicId":"sc-A7","stem":"Adolescente com episódios estereotipados de olhar fixo, automatismos e confusão de 1 minuto realiza EEG de rotina interictal que não demonstra descargas epileptiformes. O médico diz que epilepsia está excluída. Qual afirmação corrige o erro?","options":["Um EEG normal tem sensibilidade de 100% para epilepsia.","Automatismos provam comportamento voluntário se o EEG foi normal.","A confusão após o episódio exclui atividade epiléptica.","Ausência de descarga em exame curto indica que todos os episódios são síncope.","EEG interictal normal não exclui epilepsia."],"answer":4,"analysis":["INCORRETA. Um exame normal não é teste de exclusão absoluto.","INCORRETA. Automatismos podem acompanhar crises focais.","INCORRETA. Confusão pós-ictal favorece crise focal com alteração de consciência.","INCORRETA. Semiótica e avaliação clínica diferenciam as hipóteses.","CORRETA. Descargas podem não aparecer em amostra curta fora do evento; semiótica e recorrência continuam essenciais."],"explanation":"Descargas podem não aparecer em amostra curta fora do evento; semiótica e recorrência continuam essenciais.","memorizar":"EEG NORMAL entre crises NÃO DESCARTA EPILEPSIA.","source":"Biblioteca da Trilha de Ouro SDCII A7, abordagem de crises e estado de mal; enunciados autorais. Conferir doses e sequência com PALS e protocolo local, pois referências podem diferir.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Crises convulsivas em pediatria","group":"P2 • Saúde da Criança II","competence":"EEG normal entre crises","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A7-16","topicId":"sc-A7","stem":"Menina de 7 anos apresenta dezenas de episódios diários de interrupção súbita de fala, olhar parado por 8 segundos, sem queda e com retorno imediato à atividade. A professora relata que ocorrem durante tarefas e não há confusão. Qual tipo de evento é mais provável?","options":["Crise tônico-clônica generalizada, que exigiria contrações motoras bilaterais sustentadas.","Síncope cardiogênica, que explicaria dezenas de episódios sem queda e com interrupções idênticas de segundos.","Crises de ausência típicas, de curta duração e recuperação imediata.","Crise focal prolongada com pós-ictal de horas, pois retorna imediatamente.","Dificuldade exclusiva de atenção provada sem investigação porque ocorre na escola."],"answer":2,"analysis":["INCORRETA. Não há movimentos tônico-clônicos.","INCORRETA. O padrão sugere evento epiléptico de ausência, embora diferenciais existam.","CORRETA. A duração curta, frequência elevada e ausência de pós-ictal são características de ausência típica em faixa etária escolar.","INCORRETA. Não há pós-ictal prolongado.","INCORRETA. Episódios abruptos e estereotipados requerem investigação de ausência."],"explanation":"A duração curta, frequência elevada e ausência de pós-ictal são características de ausência típica em faixa etária escolar.","memorizar":"AUSÊNCIA: desconexão breve e repetitiva, retorno IMEDIATO.","source":"Biblioteca da Trilha de Ouro SDCII A7, abordagem de crises e estado de mal; enunciados autorais. Conferir doses e sequência com PALS e protocolo local, pois referências podem diferir.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Crises convulsivas em pediatria","group":"P2 • Saúde da Criança II","competence":"ausência típica","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"moderada"},{"id":"ouro-rigor5-sc-A7-17","topicId":"sc-A7","stem":"Menino de 10 anos apresenta sensação súbita de cheiro de fumaça, depois fica imóvel, faz movimentos repetitivos de mastigação por 70 segundos e permanece confuso por minutos. Qual padrão semiológico se destaca?","options":["Crise focal com comprometimento da consciência e automatismos.","Crise de ausência típica, porque todo olhar fixo dura mais de um minuto e deixa confusão.","Tique motor isolado, pois automatismos demonstram sempre supressibilidade voluntária.","Síncope por ortostatismo, porque aura olfatória é típica de queda pressórica.","Crise generalizada tônico-clônica obrigatória pela confusão, mesmo sem fase motora bilateral."],"answer":0,"analysis":["CORRETA. Aura estereotipada, automatismos e confusão pós-ictal favorecem origem epiléptica focal.","INCORRETA. Ausências típicas são breves e sem pós-ictal relevante.","INCORRETA. O estado de consciência e pós-ictal diferenciam crise.","INCORRETA. Alucinação olfatória estereotipada favorece aura focal.","INCORRETA. Não há relato de movimentos tônico-clônicos generalizados."],"explanation":"Aura estereotipada, automatismos e confusão pós-ictal favorecem origem epiléptica focal.","memorizar":"AURA + AUTOMATISMOS + PÓS-ICTAL: crise FOCAL com consciência alterada.","source":"Biblioteca da Trilha de Ouro SDCII A7, abordagem de crises e estado de mal; enunciados autorais. Conferir doses e sequência com PALS e protocolo local, pois referências podem diferir.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Crises convulsivas em pediatria","group":"P2 • Saúde da Criança II","competence":"crise focal com consciência alterada","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A7-18","topicId":"sc-A7","stem":"Lactente de 6 meses apresenta séries de flexões abruptas do tronco e braços, principalmente ao despertar, associadas à perda de marcos de desenvolvimento nas últimas semanas. Qual urgência diagnóstica é mais importante?","options":["Classificar como reflexo de Moro fisiológico recorrente até a adolescência.","Atribuir à cólica isolada porque flexão do tronco sempre significa dor abdominal.","Aguardar anos para EEG porque crises são curtas.","Diagnosticar convulsão febril simples sem febre.","Suspeitar de espasmos infantis e obter EEG/avaliação urgente."],"answer":4,"analysis":["INCORRETA. O padrão em séries com regressão é patológico.","INCORRETA. Relação com despertar e perda de marcos sugerem origem epiléptica.","INCORRETA. Retardo diagnóstico pode prejudicar desenvolvimento.","INCORRETA. Não há febre e o padrão é de espasmos.","CORRETA. Clusters de espasmos e regressão do desenvolvimento sugerem encefalopatia epiléptica do lactente."],"explanation":"Clusters de espasmos e regressão do desenvolvimento sugerem encefalopatia epiléptica do lactente.","memorizar":"ESPASMOS EM SALVAS + REGRESSÃO: investigação EEG URGENTE.","source":"Biblioteca da Trilha de Ouro SDCII A7, abordagem de crises e estado de mal; enunciados autorais. Conferir doses e sequência com PALS e protocolo local, pois referências podem diferir.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Crises convulsivas em pediatria","group":"P2 • Saúde da Criança II","competence":"espasmos infantis","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A7-19","topicId":"sc-A7","stem":"Recém-nascido de 3 dias apresenta tremor fino de membros durante manipulação, que cessa quando o membro é suavemente contido; não há desvio ocular nem alterações autonômicas. Qual interpretação inicial é mais adequada?","options":["Crise tônico-clônica generalizada típica de lactentes maiores, confirmada pelo tremor cessável.","Considerar tremor neonatal cessável com contenção; avaliar contexto.","Estado de mal obrigatório, porque qualquer tremor neonatal exige benzodiazepínico contínuo.","Síndrome de West, definida por tremor fino induzido à manipulação.","Paralisia de Todd, porque há tremor bilateral."],"answer":1,"analysis":["INCORRETA. A semiologia neonatal é diferente e movimentos cessáveis sugerem tremor.","CORRETA. Movimentos não epilépticos podem ser provocáveis e cessar à contenção, diferentemente de muitas crises neonatais.","INCORRETA. Caracterização clínica e avaliação são necessárias antes de rotular status.","INCORRETA. Espasmos infantis têm outro padrão, tipicamente em salvas.","INCORRETA. Todd é déficit focal após crise, não tremor ativo."],"explanation":"Movimentos não epilépticos podem ser provocáveis e cessar à contenção, diferentemente de muitas crises neonatais.","memorizar":"JITTERINESS neonatal costuma ser ESTÍMULO-SENSÍVEL e CESSÁVEL à contenção.","source":"Biblioteca da Trilha de Ouro SDCII A7, abordagem de crises e estado de mal; enunciados autorais. Conferir doses e sequência com PALS e protocolo local, pois referências podem diferir.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Crises convulsivas em pediatria","group":"P2 • Saúde da Criança II","competence":"neonato tremor versus convulsão","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A7-20","topicId":"sc-A7","stem":"Adolescente de 15 anos desmaia após ficar em pé no calor, sente náusea e visão turva antes da queda, apresenta três abalos breves e recupera-se rapidamente ao deitar, sem confusão. Qual diferencial merece prioridade?","options":["Epilepsia tônico-clônica confirmada, pois qualquer abalo no desmaio define convulsão.","Estado de mal não convulsivo, porque ocorreu em pé por pouco tempo.","Crise febril simples, mesmo sem febre e fora da idade típica.","Síncope reflexa com abalos breves, pelo pródromo e recuperação.","Espasmos infantis, porque toda flexão involuntária pertence a esse diagnóstico."],"answer":3,"analysis":["INCORRETA. Abalos também podem ocorrer por hipoperfusão cerebral.","INCORRETA. A recuperação imediata é contrária a status.","INCORRETA. Não há febre e a idade é atípica.","CORRETA. Síncope pode apresentar movimentos mioclônicos curtos; recuperação rápida e gatilho postural ajudam a diferenciá-la de crise epiléptica.","INCORRETA. Espasmos infantis ocorrem em lactentes e têm outro padrão."],"explanation":"Síncope pode apresentar movimentos mioclônicos curtos; recuperação rápida e gatilho postural ajudam a diferenciá-la de crise epiléptica.","memorizar":"SÍNCOPE pode ter ABALOS; pródromo + ortostatismo + recuperação rápida ajudam.","source":"Biblioteca da Trilha de Ouro SDCII A7, abordagem de crises e estado de mal; enunciados autorais. Conferir doses e sequência com PALS e protocolo local, pois referências podem diferir.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Crises convulsivas em pediatria","group":"P2 • Saúde da Criança II","competence":"síncope com movimentos","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A7-21","topicId":"sc-A7","stem":"Menina de 12 anos cai subitamente durante corrida, tem poucos abalos e recupera a consciência. O pai faleceu subitamente aos 30 anos. ECG mostra QT prolongado. Qual erro diagnóstico é mais perigoso?","options":["Investigar arritmia/canalopatia antes de presumir epilepsia.","Realizar EEG ambulatorial como única avaliação, sem ECG ou história cardíaca.","Prescrever anticonvulsivante e permitir retorno irrestrito ao exercício sem estratificação.","Atribuir a queda a tontura benignamente esperada em todas as atletas.","Considerar o QT prolongado achado normal sem significado em criança sintomática."],"answer":0,"analysis":["CORRETA. Eventos abruptos durante exercício, com história familiar de morte súbita e QT longo, exigem investigação cardiológica urgente.","INCORRETA. O risco de canalopatia torna avaliação cardíaca indispensável.","INCORRETA. A condição pode precipitar arritmias malignas.","INCORRETA. Síncope de esforço é red flag.","INCORRETA. QT longo pode associar-se a torsades de pointes e síncope."],"explanation":"Eventos abruptos durante exercício, com história familiar de morte súbita e QT longo, exigem investigação cardiológica urgente.","memorizar":"DESMAIO NO EXERCÍCIO + MORTE SÚBITA FAMILIAR + QT LONGO: investigar ARRITMIA.","source":"Biblioteca da Trilha de Ouro SDCII A7, abordagem de crises e estado de mal; enunciados autorais. Conferir doses e sequência com PALS e protocolo local, pois referências podem diferir.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Crises convulsivas em pediatria","group":"P2 • Saúde da Criança II","competence":"red flags cardíacos","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A7-22","topicId":"sc-A7","stem":"Menino de 8 anos teve crise controlada com benzodiazepínico, mas segue com FR 7/min, hipoventilação e elevação de CO₂ expirado. A saturação está em 97% sob oxigênio. Qual é a prioridade?","options":["Aumentar o oxigênio como única intervenção e observar CO₂ em ascensão.","Considerar FR 7/min recuperação adequada por estar menos agitado.","Retomar benzodiazepínico por ausência de movimentos antes de avaliar respiração.","Aguardar cianose franca para começar a ventilar.","Priorizar ventilação assistida e reavaliação da via aérea."],"answer":4,"analysis":["INCORRETA. Problema é ventilatório, não apenas concentração de O₂.","INCORRETA. Bradicinesia respiratória com hipercapnia é sinal de falência ventilatória.","INCORRETA. A crise parece controlada e há risco respiratório importante.","INCORRETA. Deterioração pode preceder queda de SpO₂.","CORRETA. BZD pode reduzir drive respiratório; SpO₂ normal sob suplementação não demonstra ventilação adequada."],"explanation":"BZD pode reduzir drive respiratório; SpO₂ normal sob suplementação não demonstra ventilação adequada.","memorizar":"SP02 normal COM O2 NÃO EXCLUI HIPOVENTILAÇÃO após benzodiazepínico.","source":"Biblioteca da Trilha de Ouro SDCII A7, abordagem de crises e estado de mal; enunciados autorais. Conferir doses e sequência com PALS e protocolo local, pois referências podem diferir.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Crises convulsivas em pediatria","group":"P2 • Saúde da Criança II","competence":"depressão respiratória após benzodiazepínico","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A7-23","topicId":"sc-A7","stem":"Menina de 11 anos tem dois episódios afebris de crise focal estereotipada separados por dois meses, sem distúrbio metabólico ou intoxicação identificados. Qual conceito clínico é importante?","options":["A epilepsia exige pelo menos dez crises convulsivas generalizadas.","Toda crise focal é reação emocional e não pode ser epiléptica.","Duas crises não provocadas sustentam diagnóstico de epilepsia.","Episódios separados por meses provam estado de mal contínuo.","A ausência de febre exclui epilepsia."],"answer":2,"analysis":["INCORRETA. O critério usual não exige dez episódios nem generalização.","INCORRETA. Crises focais têm origem epileptogênica cortical.","CORRETA. Epilepsia pode ser diagnosticada pela recorrência de crises não provocadas; exames complementares caracterizam síndrome/etiologia.","INCORRETA. Status é atividade prolongada sem recuperação, não episódios distantes.","INCORRETA. Crises não provocadas são justamente relevantes ao diagnóstico."],"explanation":"Epilepsia pode ser diagnosticada pela recorrência de crises não provocadas; exames complementares caracterizam síndrome/etiologia.","memorizar":"2 CRISES NÃO PROVOCADAS separadas >24 h podem estabelecer EPILEPSIA.","source":"Biblioteca da Trilha de Ouro SDCII A7, abordagem de crises e estado de mal; enunciados autorais. Conferir doses e sequência com PALS e protocolo local, pois referências podem diferir.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Crises convulsivas em pediatria","group":"P2 • Saúde da Criança II","competence":"classificação de epilepsia","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"difícil"},{"id":"ouro-rigor5-sc-A7-24","topicId":"sc-A7","stem":"Menino de 9 anos sofre primeira crise afebril generalizada de 90 segundos, recupera-se e está neurologicamente normal. Sem história de epilepsia, trauma ou infecção. Qual estratégia posterior é mais apropriada?","options":["Instituir politerapia antiepiléptica vitalícia obrigatória antes de qualquer investigação.","Avaliar etiologia e risco antes de decidir medicação contínua.","Ignorar completamente o evento porque a crise cessou sem intervenção.","Realizar intubação profilática por semanas em toda primeira crise curta resolvida.","Diagnosticar meningite bacteriana sem febre, sinais ou exames."],"answer":1,"analysis":["INCORRETA. Uma crise isolada não obriga politerapia permanente.","CORRETA. Uma primeira crise não provocada exige avaliação neurológica, mas tratamento crônico depende de risco de recorrência e contexto clínico.","INCORRETA. A avaliação de fatores de risco e segurança é necessária.","INCORRETA. Não há indicação para suporte invasivo prolongado.","INCORRETA. Não existem evidências específicas dessa etiologia."],"explanation":"Uma primeira crise não provocada exige avaliação neurológica, mas tratamento crônico depende de risco de recorrência e contexto clínico.","memorizar":"PRIMEIRA CRISE NÃO PROVOCADA: investigar causa e RISCO DE RECORRÊNCIA.","source":"Biblioteca da Trilha de Ouro SDCII A7, abordagem de crises e estado de mal; enunciados autorais. Conferir doses e sequência com PALS e protocolo local, pois referências podem diferir.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Crises convulsivas em pediatria","group":"P2 • Saúde da Criança II","competence":"primeira crise afebril","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"difícil"},{"id":"ouro-rigor5-sc-A7-25","topicId":"sc-A7","stem":"Escolar de 7 anos apresenta primeira crise afebril focal com déficit neurológico persistente horas depois. Qual elemento modifica a necessidade de investigação estrutural urgente?","options":["Toda primeira crise dispensa imagem independentemente de déficit focal.","A focalidade exclui lesão intracraniana porque descargas focais são sempre idiopáticas.","O déficit deve ser assumido como Todd sem qualquer avaliação por ser frequente.","Investigar lesão intracraniana após crise focal com déficit persistente.","Investigar somente alergia alimentar como explicação do déficit unilateral."],"answer":3,"analysis":["INCORRETA. Sinal neurológico persistente é red flag.","INCORRETA. Focalidade pode decorrer de lesão estrutural.","INCORRETA. Todd é diferencial, mas não pode excluir causas graves automaticamente.","CORRETA. Déficit focal prolongado pode refletir AVC, massa, infecção ou alteração pós-ictal e exige avaliação mais urgente que evento generalizado breve sem alterações.","INCORRETA. Não há conexão clínica sustentada."],"explanation":"Déficit focal prolongado pode refletir AVC, massa, infecção ou alteração pós-ictal e exige avaliação mais urgente que evento generalizado breve sem alterações.","memorizar":"PRIMEIRA CRISE + DÉFICIT FOCAL PERSISTENTE: buscar CAUSA ESTRUTURAL.","source":"Biblioteca da Trilha de Ouro SDCII A7, abordagem de crises e estado de mal; enunciados autorais. Conferir doses e sequência com PALS e protocolo local, pois referências podem diferir.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Crises convulsivas em pediatria","group":"P2 • Saúde da Criança II","competence":"neuroimagem após focalidade","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A7-26","topicId":"sc-A7","stem":"Adolescente de 13 anos sofre traumatismo cranioencefálico com rebaixamento, seguido de crise convulsiva e vômitos. Qual conduta diagnóstica deve evitar a interpretação como epilepsia primária?","options":["Considerar epilepsia idiopática confirmada porque a crise ocorreu após queda.","Investigar lesão cerebral traumática como causa aguda provocadora.","Fazer somente exame eletroencefalográfico eletivo meses depois, ignorando deterioração.","Descartar hemorragia porque a crise durou menos de 5 minutos.","Atribuir vômitos e sonolência a efeitos obrigatórios da puberdade."],"answer":1,"analysis":["INCORRETA. Trauma é fator precipitante e também pode estar associado a evento secundário.","CORRETA. Convulsão em contexto de trauma e deterioração exige investigar hemorragia/contusão e risco de hipertensão intracraniana.","INCORRETA. Trauma e rebaixamento exigem avaliação urgente.","INCORRETA. Duração breve não exclui lesão estrutural.","INCORRETA. Sintomas após TCE são alarmantes."],"explanation":"Convulsão em contexto de trauma e deterioração exige investigar hemorragia/contusão e risco de hipertensão intracraniana.","memorizar":"CRISE APÓS TCE + REBAIXAMENTO: pensar em LESÃO TRAUMÁTICA AGUDA.","source":"Biblioteca da Trilha de Ouro SDCII A7, abordagem de crises e estado de mal; enunciados autorais. Conferir doses e sequência com PALS e protocolo local, pois referências podem diferir.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Crises convulsivas em pediatria","group":"P2 • Saúde da Criança II","competence":"crises após trauma","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A7-27","topicId":"sc-A7","stem":"Na escola, professora observa aluno convulsionando há 1 minuto no chão. Não há trauma importante, e o serviço de emergência já foi acionado. Qual medida de primeiros socorros é correta enquanto aguarda?","options":["Introduzir os dedos na boca para impedir deglutição da língua.","Segurar todos os membros com força para cessar a crise.","Proteger de trauma, cronometrar, não conter nem colocar objetos na boca.","Oferecer água por boca durante os movimentos.","Não medir duração porque o tempo não modifica urgência."],"answer":2,"analysis":["INCORRETA. A língua não é deglutida e a manobra pode causar mordedura e obstrução.","INCORRETA. Contenção pode causar trauma musculoesquelético.","CORRETA. Primeiros socorros visam evitar lesões e aspiração, documentar tempo e reconhecer necessidade de atendimento sem manobras traumáticas.","INCORRETA. Risco de aspiração.","INCORRETA. Tempo é essencial para reconhecer status e orientar equipe."],"explanation":"Primeiros socorros visam evitar lesões e aspiração, documentar tempo e reconhecer necessidade de atendimento sem manobras traumáticas.","memorizar":"PRIMEIROS SOCORROS: PROTEGER, CRONOMETRAR, NÃO CONTER, NADA NA BOCA.","source":"Biblioteca da Trilha de Ouro SDCII A7, abordagem de crises e estado de mal; enunciados autorais. Conferir doses e sequência com PALS e protocolo local, pois referências podem diferir.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Crises convulsivas em pediatria","group":"P2 • Saúde da Criança II","competence":"orientação primeiros socorros","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"moderada"},{"id":"ouro-rigor5-sc-A7-28","topicId":"sc-A7","stem":"Menina de 4 anos tem crise convulsiva com febre, mas após cessar permanece com rigidez nucal, irritabilidade intensa e fotofobia, sem retorno ao comportamento habitual. Qual mudança na investigação é indicada?","options":["Dar alta obrigatoriamente porque toda convulsão com febre é benigna.","Afirmar que a rigidez é sempre efeito inofensivo da contração muscular.","Recomendar apenas antitérmico e dispensar reavaliação do estado mental.","Investigar meningite/encefalite diante de sinais meníngeos persistentes.","Classificar como ausência típica por haver fotofobia."],"answer":3,"analysis":["INCORRETA. Sinais neurológicos persistentes são de risco.","INCORRETA. Rigidez nucal pode sinalizar meningite.","INCORRETA. Alteração de consciência exige avaliação.","CORRETA. Sinais meníngeos e alteração persistente do exame afastam classificação tranquilizadora de crise febril simples.","INCORRETA. A semiótica não corresponde a ausência."],"explanation":"Sinais meníngeos e alteração persistente do exame afastam classificação tranquilizadora de crise febril simples.","memorizar":"FEBRE + CRISE + SINAIS MENÍNGEOS/PÓS-ICTAL ATÍPICO: investigar SNC.","source":"Biblioteca da Trilha de Ouro SDCII A7, abordagem de crises e estado de mal; enunciados autorais. Conferir doses e sequência com PALS e protocolo local, pois referências podem diferir.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Crises convulsivas em pediatria","group":"P2 • Saúde da Criança II","competence":"sinal de infecção do SNC","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A7-29","topicId":"sc-A7","stem":"Pré-adolescente chega com agitação, midríase, taquicardia e convulsão após acesso a comprimidos de antidepressivo tricíclico de familiar. ECG revela QRS alargado. Qual avaliação adicional torna o caso particularmente perigoso?","options":["Assumir crise febril por possível temperatura ambiente elevada, ignorando ECG.","Concluir que todo antidepressivo causa apenas sedação sem cardiotoxicidade.","Prescrever alta sem observação porque a convulsão cessou.","Diagnosticar ausência típica porque houve alteração de consciência.","Considerar cardiotoxicidade por tricíclico com QRS alargado."],"answer":4,"analysis":["INCORRETA. Toxicidade e QRS alargado são dados centrais.","INCORRETA. Tricíclicos têm efeitos anticolinérgicos e bloqueio de canais de sódio.","INCORRETA. O risco de arritmia pode persistir.","INCORRETA. A crise e intoxicação são quadro agudo distinto.","CORRETA. Antidepressivos tricíclicos podem produzir convulsões e distúrbio de condução cardíaca grave; ECG anormal muda estabilização."],"explanation":"Antidepressivos tricíclicos podem produzir convulsões e distúrbio de condução cardíaca grave; ECG anormal muda estabilização.","memorizar":"TRICÍCLICO + CONVULSÃO + QRS LARGO = CARDIOTOXICIDADE.","source":"Biblioteca da Trilha de Ouro SDCII A7, abordagem de crises e estado de mal; enunciados autorais. Conferir doses e sequência com PALS e protocolo local, pois referências podem diferir.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Crises convulsivas em pediatria","group":"P2 • Saúde da Criança II","competence":"crise por intoxicação","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A7-30","topicId":"sc-A7","stem":"Menina de 5 anos fica imóvel por alguns segundos durante choro intenso, torna-se cianótica e desmaia, recuperando-se rapidamente ao ser deitada. Episódios ocorrem após frustração e têm história estereotipada. Qual diferencial merece ser considerado?","options":["Considerar espasmo do choro como evento não epiléptico.","Epilepsia refratária confirmada apenas pelo desmaio após choro.","Estado de mal epiléptico, já que a criança perdeu consciência por segundos.","Convulsão febril complexa, mesmo sem febre.","Encefalite obrigatória, porque ficou cianótica."],"answer":0,"analysis":["CORRETA. Episódio gatilhado por choro/frustração com apneia breve e recuperação rápida é compatível com espasmo do choro.","INCORRETA. Gatilho emocional e recuperação rápida sugerem evento não epiléptico.","INCORRETA. Status exige crise prolongada ou repetida sem recuperação.","INCORRETA. Não há infecção febril relatada.","INCORRETA. Sem febre ou alteração neurológica persistente, outra hipótese é mais provável."],"explanation":"Episódio gatilhado por choro/frustração com apneia breve e recuperação rápida é compatível com espasmo do choro.","memorizar":"CHORO → APNEIA/Cianose → perda breve: considerar ESPASMO DO CHORO.","source":"Biblioteca da Trilha de Ouro SDCII A7, abordagem de crises e estado de mal; enunciados autorais. Conferir doses e sequência com PALS e protocolo local, pois referências podem diferir.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Crises convulsivas em pediatria","group":"P2 • Saúde da Criança II","competence":"história de evento não epiléptico","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"difícil"}]};
